/**
 * Sanctum Studio - React / Web Components Code Exporter
 * Recursive AST Compiler generating semantic, accessible React components with Tailwind container queries
 */

export function exportToReact(doc) {
  const componentName = (doc.meta?.title || 'SanctumView').replace(/[^a-zA-Z0-9]/g, '');
  const compiledAstTree = compileNodeToReact(doc.masterPrototype, '        ');

  return `// =====================================================================
// Generated by Sanctum Studio - React & Tailwind Target
// Title: ${doc.meta?.title || 'Untitled'} (${doc.meta?.subtype || 'custom'})
// Generated at: ${new Date().toISOString()}
// =====================================================================

import React, { useState } from 'react';

export function ${componentName}({ onAction }) {
  const [state, setState] = useState('ready');

  const handleSubmit = (actionName) => {
    setState('running');
    if (onAction) onAction(actionName || 'SUBMIT');
  };

  return (
    <div className="s-app w-full min-h-screen bg-[var(--surface-canvas)] text-[var(--text-primary)] font-['IBM_Plex_Sans',sans-serif] p-[1em] @container">
      <div className="max-w-[76em] mx-auto flex flex-col gap-[1em]">
        
        {/* Header Section */}
        <header className="bg-[var(--surface-card)] border border-[var(--surface-border)] rounded-[0.75em] p-[1.25em] flex flex-col @[48em]:flex-row justify-between items-start @[48em]:items-center gap-[0.75em]">
          <div>
            <h1 className="text-[1.5em] font-semibold tracking-tight m-0">${doc.meta?.title || 'Page'}</h1>
            <p className="text-[0.875em] text-[var(--text-secondary)] m-0 mt-[0.25em]">Subtype: ${doc.meta?.subtype || 'custom'}</p>
          </div>
          <span 
            role="status" 
            aria-live="polite"
            className="inline-flex items-center px-[0.75em] py-[0.25em] rounded-full text-[0.75em] font-mono font-medium tracking-wide bg-[var(--action-primary)]/20 text-[var(--action-primary)]"
          >
            {state.toUpperCase()}
          </span>
        </header>

        {/* Recursively Compiled Layout AST */}
${compiledAstTree}
${!compiledAstTree.includes('min-h-[2.75em]') ? `        <button type="button" onClick={() => handleSubmit('EXECUTE')} className="inline-flex items-center justify-center min-h-[2.75em] px-[1.25em] py-[0.5em] rounded-[0.5em] bg-[var(--action-primary)] text-[#0B0C10] font-medium transition hover:brightness-110">Execute Workflow</button>` : ''}

      </div>
    </div>
  );
}
`;
}

function compileNodeToReact(node, indent = '        ') {
  if (!node) return '';
  const p = node.props || {};
  let childrenCode = '';
  if (node.children && node.children.length > 0) {
    childrenCode = node.children.map(c => compileNodeToReact(c, indent + '  ')).filter(Boolean).join('\n\n');
  }

  switch (node.type) {
    case 'AppShell':
      return childrenCode;

    case 'CardWidget':
      return `${indent}<section className="bg-[var(--surface-card)] border border-[var(--surface-border)] rounded-[0.75em] p-[1.5em] flex flex-col gap-[1em]">
${indent}  <div>
${indent}    <h2 className="text-[1.125em] font-medium m-0">${p.title || node.name || 'Card Widget'}</h2>
${p.subtitle ? `${indent}    <p className="text-[0.875em] text-[var(--text-secondary)] m-0 mt-[0.25em]">${p.subtitle}</p>\n` : ''}${indent}  </div>
${childrenCode ? `${indent}  <div className="flex flex-col gap-[0.75em]">\n${childrenCode}\n${indent}  </div>` : ''}
${indent}</section>`;

    case 'Button':
      const isPrimary = p.variant === 'primary';
      const bgClass = isPrimary 
        ? 'bg-[var(--action-primary)] text-[#0B0C10] hover:brightness-110' 
        : 'bg-[var(--surface-card)] border border-[var(--surface-border)] text-[var(--text-primary)] hover:border-[var(--action-primary)]';
      return `${indent}<button
${indent}  type="button"
${indent}  onClick={() => handleSubmit('EXECUTE')}
${indent}  className="inline-flex items-center justify-center min-h-[2.75em] px-[1.25em] py-[0.5em] rounded-[0.5em] font-medium text-[0.9375em] transition ${bgClass} focus-visible:outline focus-visible:outline-2 focus-visible:outline-[var(--action-primary)]"
${indent}>
${indent}  ${p.label || 'Action'}
${indent}</button>`;

    case 'Input':
      return `${indent}<div className="flex flex-col gap-[0.25em]">
${indent}  <label className="text-[0.75em] text-[var(--text-secondary)] font-medium">${p.label || 'Input'}</label>
${indent}  <input 
${indent}    type="text" 
${indent}    placeholder="${p.placeholder || ''}" 
${indent}    className="bg-[var(--surface-canvas)] border border-[var(--surface-border)] rounded-[0.375em] px-[0.75em] py-[0.5em] text-[0.875em] text-[var(--text-primary)] focus:outline-none focus:border-[var(--action-primary)]" 
${indent}  />
${p.helperText ? `${indent}  <span className="text-[0.6875em] text-[var(--text-secondary)]">${p.helperText}</span>\n` : ''}${indent}</div>`;

    case 'RiskGuardBanner':
      return `${indent}<aside className="bg-[rgba(244,123,116,0.12)] border-l-[0.25em] border-[var(--action-danger)] p-[0.75em] rounded-[0.375em] flex flex-col gap-[0.25em]">
${indent}  <strong className="text-[var(--action-danger)] text-[0.875em]">⚠️ ${p.title || 'Risk Guard Active'}</strong>
${indent}  <span className="text-[var(--text-secondary)] text-[0.75em]">${p.message || ''}</span>
${indent}</aside>`;

    case 'MetricChip':
      return `${indent}<div className="bg-[var(--surface-card)] border border-[var(--surface-border)] rounded-[0.5em] p-[0.75em] flex flex-col gap-[0.25em]">
${indent}  <span className="text-[0.75em] text-[var(--text-secondary)]">${p.label || 'Metric'}</span>
${indent}  <div className="flex items-baseline gap-[0.5em]">
${indent}    <strong className="text-[1.25em] font-semibold text-[var(--accent-teal,#5EEAD4)]">${p.value || '100%'}</strong>
${indent}    <span className="text-[0.75em] text-[var(--action-primary)]">${p.trend || 'nominal'}</span>
${indent}  </div>
${indent}</div>`;

    case 'TaskRack':
      const cols = p.columns || ['Queued', 'In Flight', 'Gate', 'Done'];
      return `${indent}<div className="grid grid-cols-2 @[48em]:grid-cols-4 gap-[0.5em]">
${cols.map(c => `${indent}  <div className="bg-[var(--surface-canvas)] border border-[var(--surface-border)] rounded-[0.375em] p-[0.5em] text-[0.75em]">
${indent}    <div className="font-semibold text-[var(--action-primary)] uppercase mb-[0.25em]">${c}</div>
${indent}    <div className="bg-[var(--surface-card)] rounded p-[0.375em]">Active Task Block</div>
${indent}  </div>`).join('\n')}
${indent}</div>`;

    case 'DataTable':
      const columns = p.columns || ['ID', 'Name', 'State'];
      return `${indent}<div className="overflow-x-auto border border-[var(--surface-border)] rounded-[0.375em]">
${indent}  <table className="w-full text-left text-[0.875em] border-collapse">
${indent}    <thead className="bg-[var(--surface-canvas)] text-[var(--text-secondary)]">
${indent}      <tr>
${columns.map(col => `${indent}        <th className="p-[0.5em] border-b border-[var(--surface-border)]">${col}</th>`).join('\n')}
${indent}      </tr>
${indent}    </thead>
${indent}    <tbody>
${indent}      <tr className="hover:bg-[var(--surface-canvas)]/50">
${indent}        <td className="p-[0.5em] border-b border-[var(--surface-border)]">#01</td>
${indent}        <td className="p-[0.5em] border-b border-[var(--surface-border)]">Task Instance</td>
${indent}        <td className="p-[0.5em] border-b border-[var(--surface-border)]"><span className="text-[var(--accent-teal,#5EEAD4)]">OK</span></td>
${indent}      </tr>
${indent}    </tbody>
${indent}  </table>
${indent}</div>`;

    case 'Toggle':
      return `${indent}<label className="flex items-center justify-between py-[0.25em] cursor-pointer">
${indent}  <span className="text-[0.875em] text-[var(--text-primary)]">${p.label || 'Setting Toggle'}</span>
${indent}  <input type="checkbox" defaultChecked={${p.checked ? 'true' : 'false'}} className="accent-[var(--action-primary)] h-[1.25em] w-[1.25em]" />
${indent}</label>`;

    case 'Text':
      return `${indent}<div className="text-[0.875em] leading-relaxed text-[var(--text-primary)]">${p.content || ''}</div>`;

    default:
      return childrenCode;
  }
}
